import { extract } from 'tar';
import fetch from 'node-fetch';
import createDebug from 'debug';
import { createGunzip } from 'node:zlib';
import { pipeline } from 'node:stream/promises';
import { join } from 'node:path';
import { lstat, symlink } from 'node:fs/promises';

const debug = createDebug('@vercel/fun:install-python');

export function generatePythonTarballUrl(
	version: string,
	platform: NodeJS.Platform = process.platform,
	arch: string = process.arch,
): string {
	return `https://python-binaries.zeit.sh/python-${version}-${platform}-${arch}.tar.gz`;
}

export async function installPython(
	dest: string,
	version: string,
	platform: NodeJS.Platform = process.platform,
	arch: string = process.arch,
): Promise<void> {
	// For Apple M1 use the x64 binaries
	if (platform === 'darwin' && arch === 'arm64') {
		arch = 'x64';
	}

	const tarballUrl = generatePythonTarballUrl(version, platform, arch);
	debug('Downloading Python %s tarball %o', version, tarballUrl);
	const res = await fetch(tarballUrl);
	if (!res.ok) {
		throw new Error(`HTTP request ${tarballUrl} failed: ${res.status}`);
	}
	debug('Extracting Python %s tarball to %o', version, dest);
	await pipeline(res.body, createGunzip(), extract({ strip: 1, C: dest }));

	// tar@7.5.9+ drops symlinks whose target is itself a symlink.
	// The Python tarballs have bin/python -> python3 -> python3.6,
	// so bin/python gets silently skipped. Recreate it if missing.
	const pythonBin = join(dest, 'bin', 'python');
	try {
		await lstat(pythonBin);
	} catch {
		const target = version.startsWith('2.') ? 'python2.7' : 'python3';
		debug('Recreating missing symlink %o -> %o', pythonBin, target);
		await symlink(target, pythonBin);
	}
}

import { extract } from 'tar';
import fetch from 'node-fetch';
import createDebug from 'debug';
import { createGunzip } from 'node:zlib';
import { pipeline } from 'node:stream/promises';
import { basename, join } from 'node:path';
import { createWriteStream } from 'node:fs';
import { satisfies } from 'semver';
import { unzip, zipFromFile } from './unzip';

const debug = createDebug('@vercel/fun:install-node');

export function generateNodeTarballUrl(
	version: string,
	platform: NodeJS.Platform = process.platform,
	arch: string = process.arch,
): string {
	if (!version.startsWith('v')) {
		version = `v${version}`;
	}
	let ext: string;
	let plat: string = platform;
	if (platform === 'win32') {
		ext = 'zip';
		plat = 'win';
	} else {
		ext = 'tar.gz';
	}
	return `https://nodejs.org/dist/${version}/node-${version}-${plat}-${arch}.${ext}`;
}

export async function installNode(
	dest: string,
	version: string,
	platform: NodeJS.Platform = process.platform,
	arch: string = process.arch,
): Promise<void> {
	// For Apple M1, use the x64 binaries for v14 or less,
	// since there are no arm64 binaries for these versions
	if (
		platform === 'darwin' &&
		arch === 'arm64' &&
		satisfies(version, '<= 14')
	) {
		arch = 'x64';
	}

	const tarballUrl = generateNodeTarballUrl(version, platform, arch);
	debug('Downloading Node.js %s tarball %o', version, tarballUrl);
	const res = await fetch(tarballUrl);
	if (!res.ok) {
		throw new Error(`HTTP request failed: ${res.status}`);
	}
	if (platform === 'win32') {
		// Put it in the `bin` dir for consistency with the tarballs
		const finalDest = join(dest, 'bin');
		const zipName = basename(tarballUrl);
		const zipPath = join(dest, zipName);

		debug('Saving Node.js %s zip file to %o', version, zipPath);
		await pipeline(res.body, createWriteStream(zipPath));

		debug('Extracting Node.js %s zip file to %o', version, finalDest);
		const zipFile = await zipFromFile(zipPath);
		await unzip(zipFile, finalDest, { strip: 1 });
	} else {
		debug('Extracting Node.js %s tarball to %o', version, dest);
		await pipeline(
			res.body,
			createGunzip(),
			extract({ strip: 1, C: dest }),
		);
	}
}

