let pythonBin = 'python3';
function fallback() {
	pythonBin = 'python';
}
function handler(data?: string) {
	const isPython3 = data && data.startsWith('Python 3');

	if (!isPython3) {
		fallback();
	}

	const bootstrap = join(__dirname, '..', 'python', 'bootstrap.py');
	spawn(pythonBin, [bootstrap], { stdio: 'inherit' });
